gaYR(){return"\u042f\u043a\u0449\u043e \u0432\u0438 \u0437\u0432\u0456\u0440\u044f\u0454\u0442\u0435 \u0456\u043d\u0448\u043e\u0433\u043e \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447\u0430, \u0432\u0438 \u043c\u043e\u0436\u0435\u0442\u0435 \u0431\u0443\u0442\u0438 \u0432\u043f\u0435\u0432\u043d\u0435\u043d\u0456, \u0449\u043e \u0437\u043d\u0430\u0454\u0442\u0435, \u043a\u043e\u043c\u0443 \u0432\u0438 \u043d\u0430\u0441\u043f\u0440\u0430\u0432\u0434\u0456 \u043f\u0438\u0448\u0435\u0442\u0435. \ud83d\udcaa\n\n\u041a\u043e\u043b\u0438 \u0432\u0438 \u043f\u043e\u0447\u043d\u0435\u0442\u0435 \u0437\u0432\u0456\u0440\u0435\u043d\u043d\u044f, \u0432\u0438 \u0442\u0430 \u0456\u043d\u0448\u0438\u0439 \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u0447 \u043f\u043e\u0431\u0430\u0447\u0438\u0442\u0435 \u0441\u043f\u043b\u0438\u0432\u043d\u0435 \u0432\u0456\u043a\u043d\u043e \u0432 \u0437\u0430\u0441\u0442\u043e\u0441\u0443\u043d\u043a\u0443. \u0422\u0430\u043c \u0432\u0438 \u043f\u043e\u0431\u0430\u0447\u0438\u0442\u0435 \u043d\u0430\u0431\u0456\u0440 \u0441\u043c\u0430\u0439\u043b\u0438\u043a\u0456\u0432 \u0430\u0431\u043e \u0447\u0438\u0441\u0435\u043b, \u044f\u043a\u0456 \u0432\u0430\u043c \u043f\u043e\u0442\u0440\u0456\u0431\u043d\u043e \u0431\u0443\u0434\u0435 \u043f\u043e\u0440\u0456\u0432\u043d\u044f\u0442\u0438 \u043c\u0456\u0436 \u0441\u043e\u0431\u043e\u044e.\n\n\u041d\u0430\u0439\u043a\u0440\u0430\u0449\u0438\u0439 \u0441\u043f\u043e\u0441\u0456\u0431 \u0437\u0440\u043e\u0431\u0438\u0442\u0438 \u0446\u0435 \u2014 \u0437\u0443\u0441\u0442\u0440\u0456\u0442\u0438\u0441\u044f \u0430\u0431\u043e \u0440\u043e\u0437\u043f\u043e\u0447\u0430\u0442\u0438 \u0432\u0456\u0434\u0435\u043e\u0432\u0438\u043a\u043b\u0438\u043a. \ud83d\udc6d"},
